4	// DecDwSpec at DW_STAGE=1 (default) is 72 bytes (verified vs device layout below).
5	static const int kDwSpecBytes = 72;
6	// DecTcSmem layout (bytes):
7	//  sA: kDecRingStages * kDecAtomsPerSlot * 64 * 16 * sizeof(bf16=2)
8	//  sB: kDecRingStages * TILE_N * 16 * 2
9	//  red: 256*4 = 1024
10	//  spec: 9 * 72 = 648
11	// alignof 16 (the alignas(16) on sA). Trailing pad to multiple of 16.
12	long smem(int TILE_M, int TILE_N, int IL, int S){
13	    int kAtomsM = TILE_M/64;
14	    int kDecAtomsPerSlot = std::min(kAtomsM, IL);
15	    long sA = (long)S*kDecAtomsPerSlot*64*16*2;
16	    long sB = (long)S*TILE_N*16*2;
17	    long red = 1024;
18	    long spec = 9*72;
19	    long raw = sA+sB+red+spec;
20	    long aligned = (raw + 15)/16*16;
21	    return aligned;
22	}
23	int main(){
24	    int TMs[]={128,64,256}, TNs[]={128,64,256}, ILs[]={2,1,3,4};
25	    printf("%-6s %-6s %-4s | %-9s %-9s %-9s | crossover(>48KB)\n","TILE_M","TILE_N","IL","S=2(KB)","S=3(KB)","S=4(KB)");
26	    const long CAP=48*1024;
27	    for(int tm: TMs) for(int tn: TNs) for(int il: ILs){
28	        long s2=smem(tm,tn,il,2), s3=smem(tm,tn,il,3), s4=smem(tm,tn,il,4);
29	        const char* note="";
30	        if(s2>CAP) note="S2 BUSTS STATIC!";
31	        else if(s3>CAP) note="S3 needs dyn (S2 static-ok)";
32	        else if(s4>CAP) note="S4 needs dyn (S2,S3 static-ok)";
33	        else note="all S<=48KB (no dyn needed)";
34	        printf("%-6d %-6d %-4d | %8.2f %8.2f %8.2f | %s\n", tm,tn,il, s2/1024.0, s3/1024.0, s4/1024.0, note);
35	    }
36	    return 0;
37	}
